import heapq
from typing import List

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        rev = [[] for _ in range(n)]
        for u, v, w in edges:
            rev[v].append((u, w))

        inf = 10**18
        dist = [inf] * n
        dist[0] = 0
        heap = [(0, 0)]

        while heap:
            cur, u = heapq.heappop(heap)
            if cur != dist[u]:
                continue

            for v, w in rev[u]:
                nxt = max(cur, w)
                if nxt < dist[v]:
                    dist[v] = nxt
                    heapq.heappush(heap, (nxt, v))

        ans = max(dist)
        return -1 if ans == inf else ans
